<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Currency Converter</title>@vite(['resources/css/app.css','resources/js/app.js'])</head>
<body class="bg-slate-100 p-6"><main class="mx-auto max-w-md rounded-2xl bg-white p-6 shadow" x-data="converter()"><h1 class="mb-6 text-2xl font-bold">Currency Converter</h1><input class="w-full rounded border p-3" x-model="amount" inputmode="decimal" @input="recalculate"><select class="mt-3 w-full rounded border p-3" x-model="from" @change="load()"><template x-for="c in currencies"><option :value="c" x-text="c"></option></template></select><button class="my-3 w-full rounded bg-slate-200 p-2" @click="swap">⇅ Swap</button><select class="w-full rounded border p-3" x-model="to" @change="load()"><template x-for="c in currencies"><option :value="c" x-text="c"></option></template></select><p class="mt-6 text-2xl font-bold" x-text="result"></p><p class="mt-2 text-sm text-slate-500" x-text="message"></p><button class="mt-5 w-full rounded bg-blue-600 p-3 text-white" @click="load(true)">↻ Refresh</button></main><script>function converter(){return{amount:'1',from:'USD',to:'BYN',factor:null,result:'',message:'',currencies:['BYN','USD','EUR','PLN','GBP','CNY','RUB','UAH','BTC','ETH','USDT','SOL','XRP'],init(){let p=JSON.parse(localStorage.getItem('currency-converter-pair')||'null');if(p&&this.currencies.includes(p.from)&&this.currencies.includes(p.to)){this.from=p.from;this.to=p.to}this.load()},swap(){[this.from,this.to]=[this.to,this.from];this.load()},recalculate(){if(this.factor&&/^\d+(?:[.,]\d+)?$/.test(this.amount))this.result=`${this.multiply(this.amount,this.factor)} ${this.to}`},multiply(a,b){let p=s=>{let[x,y='']=s.replace(',','.').split('.');return[BigInt((x+y)||0),y.length]},[x,xs]=p(a),[y,ys]=p(b),v=(x*y).toString(),s=xs+ys;if(s){v=v.padStart(s+1,'0');v=v.slice(0,-s)+'.'+v.slice(-s)}return v.replace(/\.0+$/,'').replace(/(\.\d*?)0+$/,'$1')},async load(refresh=false){this.message='Loading…';try{let r=await fetch('/conversion',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({amount:this.amount,from:this.from,to:this.to,refresh})}),d=await r.json();if(!r.ok)throw Error(d.message);this.factor=d.factor;this.result=`${d.targetDisplay} ${this.to}`;localStorage.setItem('currency-converter-pair',JSON.stringify({from:this.from,to:this.to}));this.message=d.isStale?'No network. Using cached rate.':`Updated ${new Date(d.updatedAt).toLocaleString()}`}catch(e){this.message=e.message}}}}</script></body></html>
